div.script:
document.addEventListener('DOMContentLoaded', function() {
    var toggleBtn = document.getElementById('mobileMenuToggle');
    var menu = document.querySelector('.navbar-menu');
    if (toggleBtn && menu) {
        toggleBtn.addEventListener('click', function() {
            menu.classList.toggle('active');
        });
    }
});

function setAllStatus(status) {
    var radios = document.querySelectorAll('input[type="radio"][value="' + status + '"]');
    radios.forEach(function(radio) {
        radio.checked = true;
        var card = radio.closest('.siswa-card');
        if (card) {
            card.setAttribute('data-status', status);
        }
    });
    updateStats();
}

function updateStats() {
    var statuses = ['hadir', 'izin', 'sakit', 'alfa'];
    statuses.forEach(function(status) {
        var count = document.querySelectorAll('input[type="radio"][value="' + status + '"]:checked').length;
        var statEl = document.getElementById('stat-' + status);
        if (statEl) {
            statEl.textContent = count;
        }
    });

    document.querySelectorAll('.siswa-card').forEach(function(card) {
        var checkedRadio = card.querySelector('input[type="radio"]:checked');
        if (checkedRadio) {
            card.setAttribute('data-status', checkedRadio.value);
        }
    });
}

document.addEventListener('DOMContentLoaded', function() {
    updateStats();
});
